func (d Dir) delta() (int, int) {
	switch d {
	case N:
		return 0, 1
	case E:
		return 1, 0
	case S:
		return 0, -1
	case W:
		return -1, 0
	}
	return 0, 0
}

// Step 2

// Action represents a single robot movement request forwarded from the
// robot to the room.  Values are the same as Command values ('R', 'L', 'A').
type Action Command

// dirDelta returns the unit displacement in room units for a direction.
func dirDelta(d Dir) (RU, RU) {
	dx, dy := d.delta()
	return RU(dx), RU(dy)
}

// Advance returns the position one step ahead of p in direction d.
func (p Pos) Advance(d Dir) Pos {
	dx, dy := dirDelta(d)
	return Pos{p.Easting + dx, p.Northing + dy}
}

// Contains reports whether p lies within the closed rectangle r.
func (r Rect) Contains(p Pos) bool {
	return p.Easting >= r.Min.Easting && p.Easting <= r.Max.Easting &&
		p.Northing >= r.Min.Northing && p.Northing <= r.Max.Northing
}

func StartRobot(command chan Command, action chan Action) {
	for cmd := range command {
		action <- Action(cmd)
	}
	close(action)
}

func Room(extent Rect, robot Step2Robot, action chan Action, report chan Step2Robot) {
	for act := range action {
		switch Command(act) {
		case 'R':
			robot.Dir = robot.Dir.turnRight()
		case 'L':
			robot.Dir = robot.Dir.turnLeft()
		case 'A':
			np := robot.Pos.Advance(robot.Dir)
			if extent.Contains(np) {
				robot.Pos = np
			}
		}
	}
	report <- robot
}

// Step 3

// Action3 represents an action attributed to a named robot.  A zero Cmd
// value is a sentinel meaning "this robot has finished its script".
type Action3 struct {
	Name string
	Cmd  Command
}

const doneCmd Command = 0

func StartRobot3(name, script string, action chan Action3, log chan string) {
	for i := 0; i < len(script); i++ {
		c := Command(script[i])
		switch c {
		case 'R', 'L', 'A':
			action <- Action3{name, c}
		default:
			log <- fmt.Sprintf("robot %q: undefined command %q in script", name, script[i])
			i = len(script) // stop processing the rest of the script
		}
	}
	action <- Action3{name, doneCmd}
}

func Room3(extent Rect, robots []Step3Robot, action chan Action3, rep chan []Step3Robot, log chan string) {
	seenNames := map[string]bool{}
	seenPos := map[Pos]bool{}
	for _, r := range robots {
		if r.Name == "" {
			log <- "a robot was placed without a name"
		} else if seenNames[r.Name] {
			log <- fmt.Sprintf("duplicate robot name %q", r.Name)
		} else {
			seenNames[r.Name] = true
		}
		if seenPos[r.Pos] {
			log <- fmt.Sprintf("robot %q placed at an already occupied position %v", r.Name, r.Pos)
		} else {
			seenPos[r.Pos] = true
		}
		if !extent.Contains(r.Pos) {
			log <- fmt.Sprintf("robot %q placed outside the room at %v", r.Name, r.Pos)
		}
	}

	index := map[string]int{}
	for i, r := range robots {
		if _, dup := index[r.Name]; !dup {
			index[r.Name] = i
		}
	}

	want := len(robots)
	done := 0
	for done < want {
		act := <-action
		if act.Cmd == doneCmd {
			done++
			continue
		}
		i, ok := index[act.Name]
		if !ok {
			log <- fmt.Sprintf("action from unknown robot %q", act.Name)
			continue
		}
		r := &robots[i]
		switch act.Cmd {
		case 'R':
			r.Dir = r.Dir.turnRight()
		case 'L':
			r.Dir = r.Dir.turnLeft()
		case 'A':
			np := r.Pos.Advance(r.Dir)
			if !extent.Contains(np) {
				log <- fmt.Sprintf("robot %q bumped into a wall", r.Name)
				continue
			}
			blocked := false
			for j, o := range robots {
				if j != i && o.Pos == np {
					blocked = true
					break
				}
			}
			if blocked {
				log <- fmt.Sprintf("robot %q bumped into another robot", r.Name)
				continue
			}
			r.Pos = np
		}
	}
	rep <- robots
}
